UPDATE SYS_DATA_COLLABORATION_RECORD SET SUCCESS_COUNT = #{successCount}, FAILURE_COUNT = #{failureCount}, TOTAL_COUNT = #{totalCount}, UPDATE_TIME =
NOW() SYSDATE NOW()
WHERE RECORD_ID = #{recordId}

UPDATE SYS_DATA_COLLABORATION_RECORD SET RETRY_COUNT = RETRY_COUNT + 1, UPDATE_TIME =
NOW() SYSDATE NOW()
WHERE RECORD_ID = #{recordId}
